class PolarCamera
{
  let m_camPos = new PVector(0.0,2.4,0.0);
  m_CamAngleX = 0.;
  m_CamAngleY = -0.3;
  let m_camDir;

  constructor(cpos, angX, angY )
  {
    m_camPos =cpos;
    m_CamAngleX = angX;
    m_CamAngleY = angY;
    update(0,0);
  }
  constructor()
  {
    update(0,0);
  }
  function update(dy, dz)
  {
    m_CamAngleX += dy;
    m_CamAngleY += -dz;
    m_camDir = new PVector(sin(m_CamAngleX)*cos(m_CamAngleY),
    sin(m_CamAngleY),cos(m_CamAngleX)*cos(m_CamAngleY));
  }
  function forward(v )
  {
    let f =new PVector();
    f.set(m_camDir);
    f.mult(v*0.25);
    m_camPos.add(f);
  }
  function side(v )
  {
    let f =m_camDir.cross(new PVector(0,1,0));
    f.normalize();
    f.mult(v*0.25);
    m_camPos.add(f);
  }
}

class FlyByCamera
{
  m_prevCamera=null;
  m_currentCamera =null;
  let target;
  let sposition;
  let eposition;

  let centre;
  let radius;

  let endTime;
  let startTime;

  noiseTargetStrength=0;
  noisePositionStrength=0;
  noiseFreq=10.;
  scimDist =0.75;
  flyLowDist=0.00;

  constructor( c, r ) {
    centre = c;
    radius=r;
    endTime=-111000.;
  }
  noise4DV( target,tv, freq) {
    noiseDetail(1,0.55);
    let time = tv*freq;
    let t = PVector.mult(target,freq);
    t.add(13.178,19.795,156.95);
    let it=int(time);
    t.add(137.*it,155.*it,176.*it);
    // 4D vector noise
    let nv0=new PVector( g_NoiseGen.Get(t.x,t.y,t.z),g_NoiseGen.Get(t.y,t.z,t.x),g_NoiseGen.Get(t.z,t.x,t.y) );

    t.add(137.,155.,176.);
    let nv1=new PVector( g_NoiseGen.Get(t.x,t.y,t.z),g_NoiseGen.Get(t.y,t.z,t.x),g_NoiseGen.Get(t.z,t.x,t.y) );

    // blend on time
    let ft = time-it;
    let r= lerp(nv0,nv1,ft);

    //print(r);
    return r;
  }
  function minMag( v, mm)
  {
    v.mult( max(mm/v.mag(),1.));
  }

  function newCameraMove(ldir, time) {
    flyLowDist=random(1.)<.55 ? 0.: max( random(0.2), random(0.65));
    scimDist = random(0.5, 1.1);
    // add orbit cams ->
    // add sin wave cams??
    // add motion blur?
    sposition = new PVector( random(-5.,5.),
    random(-3.,3.),
    random(-5.,5.));
    minMag( sposition,1.1);
    eposition = new PVector( random(-5.,5.),
    random(-3.,3.),
    random(-5.,5.));
    minMag( eposition,1.1);

    let r=radius*.25;

    // TODO : blend target position??
    target = new PVector( random(-r,r),
    random(-r,r),
    random(-r,r));

    if ( target.dot(ldir)<0 )
    {
      target.mult(-1.);
    }
    if ( eposition.dot(ldir)<0. && sposition.dot(ldir)<0. )
    {
      print("flip Pos");
      sposition.mult(-1.);
      assert( ( eposition.dot(ldir)>0. && sposition.dot(ldir)>0. ) ==false);
    }
    let handheldChance=.5;
    let stantionaryChance=0.5;
    let closeUpChance=0.5;
    if ( random(1.)<stantionaryChance)
    {
      target.normalize(); // look a surface    
      if ( random(1.) < closeUpChance ) {
        sposition.normalize();
        sposition.mult(random(1.1,1.5));
      }
      eposition.set(sposition);
      handheldChance=.8;
    }

    if ( flyLowDist >0.00) {
      target.normalize();
      if ( target.dot(sposition)<0.) {
        target.mult(-1.);
      }
    }
    target.add(centre);
    endTime = random(4.,16.);
    startTime= time;
    endTime+=startTime;

    if ( random(1.)<handheldChance) // handheld
    {
      noiseTargetStrength=random(0.,.5);
      noisePositionStrength=random(0.,.25);
    }
    else
    {
      noiseTargetStrength=noisePositionStrength=0.;
    }
    if ( flyLowDist >0.00) {
      noiseTargetStrength*=0.1;
      noisePositionStrength*=0.1;
    }
  }
  update( csphere, ldir, w, h, dz) {
    let time = millis()/1000.;

    let iscut = false;
    if ( time > endTime) {
      newCameraMove(ldir,time);
      iscut = true;
    }

    // option for blending
    assert( time>=startTime && time <=endTime);
    let t =  smoothstep(startTime,endTime,time);

    let position=lerp( sposition, eposition, t);
    let nvp=noise4DV(position,t,noiseFreq*.15);

    let up= new PVector(0.,1.,0.);
    up.add( PVector.mult(nvp,noisePositionStrength));
    up.normalize();
    position.add( PVector.mult(nvp,noisePositionStrength));

    // add pushing
    let d = csphere.GetHieghtCubeMap( position);
    minMag( position,d+0.01);

    let nv=noise4DV(target,t,noiseFreq);
    let tgt=PVector.add(target, PVector.mult(nv,noiseTargetStrength));
    let gaze= PVector.sub(tgt,position);

    if ( flyLowDist>0. || position.mag() < d+0.002) {
      position.normalize();
      position.mult(d+flyLowDist);

      let gt = tgt.get();
      gt.normalize();
      up=position.get();
      up.normalize();
      let bnrm=gt.cross(position); 

      let ntgt=bnrm.cross(position);
      gaze =ntgt;
      //     gaze.normalize();
      gaze=tgt.get();
      gaze.sub(position);
      gaze.normalize();
      gaze.mult(scimDist);
      gt = ntgt.get();
      gt.normalize();
      gaze.add(gt);
      gaze.normalize();

      //up.add(PVector.mult(gaze,100.));
      // up=tgt.cross(bnrm);
      up.mult(-1.);
    }

    m_prevCamera =  m_currentCamera;
    m_currentCamera= new Camera(position,up, gaze, w,h,dz);
    if ( iscut || m_prevCamera==null)
      m_prevCamera = m_currentCamera;
    return m_currentCamera;
  }
}
class Camera
{
  let position;
  let lower_left_corner;
  let uvw_u;
  let uvw_v;
  let uvw_w;

  constructor(eye, up, gaze,
  resX, resY, d)
  {
    position = eye;
    uvw_v = up;
    uvw_w = gaze;
    uvw_u = uvw_v.cross(uvw_w);
    uvw_u.normalize();

    uvw_v = uvw_w.cross(uvw_u );
    uvw_v.normalize();

    uvw_w.normalize();

    let sX = -resX/2;
    let sY = -resY/2;
    let eX = resX/2;
    let eY = resY/2;

    lower_left_corner = new PVector();
    let t1= new PVector();
    let t2= new PVector();
    t1.set( uvw_w);
    t1.mult(d);
    t2.set(uvw_v);
    t2.mult(sY);
    lower_left_corner.set( uvw_u);
    lower_left_corner.mult(sX);
    lower_left_corner.add(t1);
    lower_left_corner.add(t2);

    //uvw_u.mult(resX);
    //uvw_v.mult( resY);
  }
  getOrigin() {
    return position.get();
  }
  generateDirectionUnNorm( screenCoordX, screenCoordY )
  {
    let up =new PVector();
    let acc =new PVector();
    let direction = new PVector();
    direction.set( lower_left_corner );
    up.set( uvw_v);
    up.mult( screenCoordY);
    acc.set(uvw_u);
    acc.mult( screenCoordX);
    direction.add(up);
    direction.add(acc);
    return direction;
  }
  generateDirection( screenCoordX, screenCoordY )
  {
    let up =new PVector();
    let acc =new PVector();
    let direction = new PVector();
    direction.set( lower_left_corner );
    up.set( uvw_v);
    up.mult( screenCoordY);
    acc.set(uvw_u);
    acc.mult( screenCoordX);
    direction.add(up);
    direction.add(acc);
    direction.normalize();
    return direction;
  }
};



