interface CubeFiller
{
  function getNumElements();
  function Fill(dir, idx, face, w,wSize,dsamples );
}
class SpaceFiller implements CubeFiller
{

  function Fill(rd, idx, faces, w, wSize,dsamples )
  { 
    let detailClouds=g_NoiseGen.Turb3( rd.x*4.,rd.y*4., rd.z*4., 7, 0.6, 2.);
    let clouds=max(g_NoiseGen.Fbm3( rd.x,rd.y, rd.z, 7, 0.6, 2.),0.);
    detailClouds=smoothstep(0.2,0.,detailClouds);
    clouds+=detailClouds*clouds;

    // add horizon
    let dhorizGalaxy=g_NoiseGen.Turb3( rd.x*8.,rd.y*8., rd.z*8., 7, 0.65, 2.) -(sqrt(abs(rd.y))*2.-1.);
    dhorizGalaxy*=constrain( rd.z*2.,0.,1.);
    dhorizGalaxy=constrain(dhorizGalaxy,0.,2.);
    faces[idx++]=max(clouds,dhorizGalaxy);
  }
  getNumElements() {
    return 1;
  }
}

class HeightFiller implements CubeFiller
{
  let sph;
  constructor( s) {
    sph=s;
  }

  function Fill(d, idx, faces, w, wSize,dsamples )
  {      
    let h=0.;
    // blur hieght using 4 dir vectors
    // get bi and ti

    for (i=0;i<dsamples.length;i++) {     
      let p=dsamples[i].get();
      p.mult(sph.radius);
      p.add(sph.c);   
      h+=sph.GetHieght(p,-wSize);
    }
    h*=1./float(dsamples.length);
    assert( h>=0.);
    // assert( h <=sph.hgts.GetMaxHieght());
    faces[idx]=h;
    // do per planet type caching of material params
  }
  getNumElements() {
    return 1;
  }
}
class TerrainFiller implements CubeFiller
{
  let sph;
  constructor( s) {
    sph=s;
  }

  function Fill(d, idx, faces, w, wSize,dsamples )
  {      
    let p=d.get();
    p.mult(sph.radius);
    p.add(sph.c);
    let mt=sph.GetMaterial(p,-wSize);
    // do per planet type caching of material params
    faces[idx++]=mt.surfcol.x;
    faces[idx++]=mt.surfcol.y;
    faces[idx++]=mt.surfcol.z;

    faces[idx++]=mt.nrm.x;
    faces[idx++]=mt.nrm.y;
    faces[idx++]=mt.nrm.z;        

    faces[idx++]=mt.ao;
    faces[idx++]=mt.specAmount;

    faces[idx++]=mt.emiss.x;
    faces[idx++]=mt.emiss.y;
    faces[idx++]=mt.emiss.z;
  }
  getNumElements() {
    return 11;
  }
}
class CloudFiller implements CubeFiller
{
  let sph; 
  let cl;

  constructor( s, c ) {
    sph=s;
    cl=c;
  }

  function Fill(d, idx, faces, w, wSize,dsamples) {      
    let p=d.get();
    p.mult(sph.radius);
    p.add(sph.c);

    faces[idx]=cl.GetDensity(p.x,p.y,p.z, -wSize);
    faces[idx] = min(faces[idx],1.);
  }
  getNumElements() {
    return 1;
  }
};

class CubeFace
{
  let vals;
  let m_wSize;
  let m_wf;
  let m_w;
  let m_wMask;
  constructor( wSize, numFloats) {
    let w = (1<<wSize);
    m_wMask=w-1;

    m_wf=float(w)-1.;
    m_w=w;
    m_wSize=wSize;
    vals=new Array(w*w*numFloats);
  }
}; 


class FillCubeFace implements Runnable
{
  let wSize;
  let filler;
  let f;
  let numFloatsPerEl;
  let res;
  let wc;

  constructor( _filler, _wSize, 
  fi, _numFloatsPerEl,_res) {
    filler=_filler;
    wSize=_wSize;
    f = fi;
    res=_res;
    numFloatsPerEl=_numFloatsPerEl;
  }
  function run() {
    let w = (1<<wSize);
    let cf=new CubeFace(wSize,numFloatsPerEl);

    //TODO : use better sampling of directions ->
    // add other tasks if bigg?
    let dx=(.5/float(w))*2.;
    let dy=(.5/float(w))*2.;
    let dsamples = new Array(5);
    for (i=0;i<w;i++) {
      let y=(float(i))/(float(w)-1.);   
      y=y*2.-1.;
      for (j=0;j<w;j++) {
        let x=(float(j))/(float(w)-1.);         
        let d= getCubeDir( x*2.-1,y,f); 
        d.normalize();
        dsamples[0]= getCubeDir( max(x*2.-1-dx,-1.),y,f); 
        dsamples[1]= getCubeDir( min(x*2.-1+dx,1.),y,f); 
        dsamples[2]= getCubeDir( x*2.-1,max(y-dy,-1.),f);
        dsamples[3]= getCubeDir( x*2.-1,min(y+dy,1.),f);  
        for(k=0;k<4;k++)
          dsamples[k].normalize();
        dsamples[4]=d;
        let idx = (i*w+j)*numFloatsPerEl;
        filler.Fill( d, idx, cf.vals,wSize,wSize,dsamples);
      }
    }
    // now assign it.
    res[f]=cf;
  }
}     

function getCubeDir( x, y, fi)
{
  let r = new PVector(0.,0.,0.);
  assert(x>=-1.&& x<=1.);
  assert(y>=-1.&& y<=1.);

  switch(fi) {
  case 0:  //+x
    r=new PVector(1.,x,y);
    break;
  case 1:  //-x
    r=new PVector(-1.,x,y);
    break;
  case 2:  //+y
    r=new PVector(y,1,x);
    break;
  case 3:  //-y 
    r=new PVector(y,-1,x);
    break;
  case 4:  //+z
    r=new PVector(x,y,1);
    break;
  case 5:  //-z 
    r=new PVector(x,y,-1);
    break;
  }
  return r;
}

