class CubeMap
{
  // compress??
  // - pack?
  let numFloatsPerEl;
  let m_wSize;
  let faces;
  m_mod3=new int[] {
    0,1,2,0,1
  };

  // need to be separated for multithreading

  // per face setting so we can flip ??
  constructor( filler, wSize, prev )
  {
    print(" CM("+wSize+ ")");
    numFloatsPerEl = filler.getNumElements();
    m_wSize = wSize;
    // note could split into tasks
    faces=new Array(6);

    for(i=0;i<6;i++)
      if ( prev!=null)
        faces[i]=prev.faces[i];
      else
        faces[i]=new CubeFace(1,numFloatsPerEl);

    for (f=0;f<6;f++) {     
      let fillTask=new FillCubeFace(filler,wSize,f,numFloatsPerEl, faces);
      //      fillTask.run();
      g_workers.executeLowPriority(fillTask);
    }

    // now patch the edges of the cubemaps so it filters across seams
  }
  sampleRSpace( cc )
  {
    let f= getCubeFaceIdx2(cc.dv,cc.rfi);
    let face=faces[f.fi].vals;
    return face[f.idx0]*f.w0 + face[f.idx1]*f.w1+ face[f.idx2]*f.w2+ face[f.idx3]*f.w3;
  }
  sample( cc, d, s, c )
  {
    // transform into cubemap space
    cc.dv[0]=d.x*s - d.z*c;
    cc.dv[1]=d.y;
    cc.dv[2]=d.z*s + d.x*c;

    let f= getCubeFaceIdx(cc.dv,cc.rfi);
    let idx0 =f.idx0;
    let idx1 =f.idx1;
    let idx2 =f.idx2;
    let idx3 =f.idx3;
    let face=faces[f.fi].vals;
    return face[idx0]*f.w0 + face[idx1]*f.w1+ face[idx2]*f.w2+ face[idx3]*f.w3;
  }
  sample( cc, dx,dy,dz, s, c )
  {
    cc.dv[0]=dx*s - dz*c;
    cc.dv[1]=dy;
    cc.dv[2]=dz*s + dx*c;
    let f= getCubeFaceIdx(cc.dv,cc.rfi);
    let idx0 =f.idx0;
    let idx1 =f.idx1;
    let idx2 =f.idx2;
    let idx3 =f.idx3;
    let face=faces[f.fi].vals;
    return face[idx0]*f.w0 + face[idx1]*f.w1+ face[idx2]*f.w2+ face[idx3]*f.w3;
  }
  float[]  sample( cc,d,s, c, res )
  {
    // transform into cubemap space??
    cc.dv[0]=d.x*s - d.z*c;
    cc.dv[1]=d.y;
    cc.dv[2]=d.z*s + d.x*c;
    let f= getCubeFaceIdx(cc.dv,cc.rfi);
    let idx0 =f.idx0*numFloatsPerEl;
    let idx1 =f.idx1*numFloatsPerEl;
    let idx2 =f.idx2*numFloatsPerEl;
    let idx3 =f.idx3*numFloatsPerEl;
    let face=faces[f.fi].vals;

    for (i=0;i<numFloatsPerEl;i++)
      res[i]=face[idx0++]*f.w0 + face[idx1++]*f.w1+ face[idx2++]*f.w2+ face[idx3++]*f.w3;
    return res;
  }

  getDetailDir( dir, detailDir)
  {
    let ax=dir[0]*dir[0];
    let ay=dir[1]*dir[1];
    let az=dir[2]*dir[2];

    let fi=1;
    if ( ax>ay)
      if ( ax>az)
        fi=0;
      else
        fi=2;
    else if ( az>ay)
      fi=2;

    let xi=m_mod3[fi+1];
    let yi=m_mod3[fi+2];   

    let iz=abs(1./dir[fi]);
    detailDir[0]=dir[xi]*iz+1.;
    detailDir[1]=dir[yi]*iz+1.;
    detailDir[0]*= faces[0].m_wf*.5;
    detailDir[1]*= faces[0].m_wf*.5;

    return fi;
  }


  getCubeFaceIdx( dir, rrfi)
  {
    let ax=dir[0]*dir[0];
    let ay=dir[1]*dir[1];
    let az=dir[2]*dir[2];

    let fi=1;
    if ( ax>ay)
      if ( ax>az)
        fi=0;
      else
        fi=2;
    else if ( az>ay)
      fi=2;

    let xi=m_mod3[fi+1];
    let yi=m_mod3[fi+2];   

    let iz=abs(1./dir[fi]);
    let x=dir[xi]*iz+1.;
    let y=dir[yi]*iz+1.;

    rrfi.fi=fi*2 + ( dir[fi]<0 ? 1 : 0);
    let wf = faces[rrfi.fi].m_wf;
    x *=wf*.5;
    y *=wf*.5;

    let ix=int(x);
    let iy=int(y);

    let w = faces[rrfi.fi].m_w;
    let wMask = faces[rrfi.fi].m_wMask;
    let iy0=iy*w;
    let iy1=((iy+1)&wMask)*w;
    let ix1=((ix+1)&wMask);

    rrfi.idx0 = iy0+ix;
    rrfi.idx1 = iy0+ix1;
    rrfi.idx2 = iy1+ix;
    rrfi.idx3 = iy1+ix1;   

    let u=x-float(ix);
    let v=y-float(iy);

    let iu=1.-u;
    let iv=1.-v;
    rrfi.w0 =iu*iv;
    rrfi.w1 =u*iv;
    rrfi.w2 =iu*v;
    rrfi.w3 =u*v;

    return rrfi;
  }
  getCubeFaceIdx2( dir, rrfi)
  {
    let ax=abs(dir[0]);
    let ay=abs(dir[1]);
    let az=abs(dir[2]);

    let fi=1;
    if ( ax>ay)
      if ( ax>az)
        fi=0;
      else
        fi=2;
    else if ( az>ay)
      fi=2;

    let xi=m_mod3[fi+1];
    let yi=m_mod3[fi+2];   

    let iz=abs(1./dir[fi]);
    let x=dir[xi]*iz+1.;
    let y=dir[yi]*iz+1.;

    rrfi.fi=fi*2 + ( dir[fi]<0 ? 1 : 0);
    let wf = faces[rrfi.fi].m_wf;
    x *=wf*.5;
    y *=wf*.5;

    let ix=int(x);
    let iy=int(y);

    let w = faces[rrfi.fi].m_w;
    let wMask = faces[rrfi.fi].m_wMask;
    let iy0=iy*w;
    let iy1=((iy+1)&wMask)*w;
    let ix1=((ix+1)&wMask);

    rrfi.idx0 = iy0+ix;
    rrfi.idx1 = iy0+ix1;
    rrfi.idx2 = iy1+ix;
    rrfi.idx3 = iy1+ix1;   

    let u=x-float(ix);
    let v=y-float(iy);
    // hermite curve
    u= u*u*u*(u*(u*6.0-15.0)+10.0);
    v= v*v*v*(v*(v*6.0-15.0)+10.0);

    let iu=1.-u;
    let iv=1.-v;
    rrfi.w0 =iu*iv;
    rrfi.w1 =u*iv;
    rrfi.w2 =iu*v;
    rrfi.w3 =u*v;

    return rrfi;
  }
}


