let g_spaceCubeMap=null;

function skyColor( cc, lgt, d )
{
  let sc = 220.;
  let rd=d.get();
  if ( g_spaceCubeMap==null)  
    g_spaceCubeMap=new CubeMap( new SpaceFiller(), 8, null );

  let clouds=g_spaceCubeMap.sample(cc,rd,1.,0.);
  let v = smoothstep(0.75 - clouds*clouds*.3, 0.96,g_NoiseGen.Get(rd.x*sc+578.,rd.y*sc+578.,rd.z*sc+578.));

  // lens flare??

  // test angle?
 v *= .5+clouds;
  let sky= new PVector(v + clouds*0.025,v+ clouds*0.035,v+ clouds*0.1);
  let ang=max(d.dot(lgt._sd),0);
  let sf = ang*ang;
  sf = sf*sf;
  sf = sf*sf;
  sf = sf*sf;
  sf = sf*sf;
  sf+=smoothstep(0.995,0.9998,ang);

  sky.add(PVector.mult(lgt._sc,sf));
