function rotatevY( v, ang) {
  let nv=v.get();
  let sang=sin(ang);
  let cang=cos(ang);
  nv.x = sang*v.x-cang*v.z;
  nv.z=  sang*v.z+cang*v.x;
  return nv;
}

class Lighting
{
  let _sd;
  let _sc;
  let _am;

  let _rsd;
  let hangle = new PVector();
  constructor( sunDirection, sunUp, uc )
  {
    _sc =  new PVector(1.,0.8,0.4);
    _am  =  new PVector(0.25,0.4,0.7);
    _sd = sunDirection.get();    
    _sd.normalize();
  }
  function toObjectSpace( I, ang)
  {
    _rsd =rotatevY(_sd,ang);
    _rsd.normalize();
    hangle.set(I);
    hangle.mult(-1);
    hangle.add(_rsd);  // note could precompute
    hangle.normalize();
  }
  getShading( abFactor, shadFactor,n,
                        mat, litcol)
  {
    //? shot shadow ray?
    abFactor*=mat.ambAmount;
    let ambx=_am.x*abFactor;
    let amby=_am.y*abFactor;
    let ambz=_am.z*abFactor;
    let nd =max( n.dot(_rsd),0);

    // apply bounce depending on in shadow 
   let sunFactor=nd *shadFactor;
    let sunlightx  = ambx + _sc.x*sunFactor;
    let sunlighty  = amby + _sc.y*sunFactor;
    let sunlightz  = ambz + _sc.z*sunFactor;
    let hdotN=max(hangle.dot(n),0);
    hdotN =hdotN*hdotN;
    hdotN =hdotN*hdotN;
    hdotN =hdotN*hdotN;
    //hdotN =hdotN*hdotN;

    let spec = hdotN*mat.specAmount* shadFactor*max(abFactor*2.,1.);
    let speccolx=_sc.x*spec;
    let speccoly=_sc.y*spec;
    let speccolz=_sc.z*spec;   

    litcol.x = sunlightx*mat.surfcol.x+speccolx+mat.emiss.x;
    litcol.y = sunlighty*mat.surfcol.y+speccoly+mat.emiss.y;
    litcol.z = sunlightz*mat.surfcol.z+speccolz+mat.emiss.z;   
    return litcol;
  }
};



