    {
      s+= amp*Get(x,y);//, Wrap-1);
      x*=l;
      y*=l;
      amp *= p;
      Wrap <<=1;
    }
    return s;
  }
   Fbm3( x, y, z, oct,  p, l )
  {
    let s =0;
    let amp=1;
    for (i=0; i<oct; i++)
    {
      s+= amp*Get(z,y,x);
      x*=l;
