class HitInfo
{
  let m_hp;
  let m_nrm;
  let m_tangent;
  let m_binormal;

  let m_tu;
  let m_tv;


  constructor( hpt,c)
  {
    Setup(hpt,c);
  }
  function Setup( hpt, c)
  {
    m_hp=hpt;
    // get normal
    m_nrm = new PVector();
    m_nrm.set(m_hp);
    m_nrm.sub(c);
    m_nrm.normalize();

    let tg = new PVector();
    if ( abs(m_nrm.y)<0.99)
      tg = new PVector(0.,1.,0.);
    else
      tg = new PVector(1.,0.,0.);
    let bi = tg.cross(m_nrm);
    bi.normalize();
    tg = m_nrm.cross(bi);

    m_tangent = tg;
    m_binormal = bi;
  }
  Transform( n )
  {
    let rnrm = new PVector();
    rnrm.x = n.x*m_binormal.x + n.y * m_nrm.x + n.z*m_tangent.x;
    rnrm.y = n.x*m_binormal.y + n.y * m_nrm.y + n.z*m_tangent.y;
    rnrm.z = n.x*m_binormal.z + n.y * m_nrm.z + n.z*m_tangent.z;
    rnrm.normalize();
    return rnrm;
  }
}
