function intSphereOriginSimple( r2, d, dir)
{
  let c = d.dot(d) - r2*r2;
  let b = d.dot(dir);
  let t = b*b-c;
  if ( t > 0.0) {
    let st =sqrt(t);
    t = -b-st;
    if ( t < 0.0)
    {
      t = -b+st;
    }
    return t;
  }
  return -100.;
}
function intSphereSimple( sp, r2, ro, dir)
{
  let d = new PVector();
  d.set( ro);
  d.sub( sp);
  let c = d.dot(d) - r2*r2;
  let b = d.dot(dir);
  let t = b*b-c;
  if ( t > 0.0) {
    let st =sqrt(t);
    t = -b-st;
    if ( t < 0.0)
    {
      t = -b+st;
    }
    return t;
  }
  return -100.;
}

function intSphereBound( sp, r2, ro, dir)
{
  let d = new PVector();
  d.set( ro);
  d.sub( sp);
  let c = d.dot(d) - r2*r2;
  let b = d.dot(dir);
  let t = b*b-c;
  if ( t > 0.0) {
    let st =sqrt(t);
    return new PVector( max( -b-st, 0.), max( -b+st, 0.),0.);
  }
  return new PVector( -1., -1.);
}

class RetSurface
