let cloudHieght = 0.02;// 0.01;

class Sphere
{
  let c;
  let r2;
  let maxRad;
  let invRadius;
  let hgts;
  let radius;

  aoWrap = 0.4;
  let invWrap = (1./(1.+aoWrap));
  shadRap = .25;
  let invShadWrap = 1./(1.+shadRap);

  rangc=1.;
  rangs=0.;

  crangc=1.;
  crangs=0.;

  let rorigD;
  let rdistOrig2;
  let rrorig;
  constructor( _c, _r2, _hgts )
  {
    c=_c;
    r2 = _r2;
    radius = sqrt(r2);
    invRadius = 1./radius;
    hgts = _hgts;
    maxRad = r2+GetOuterRadius();
  }
  function setRotationAngle(orig, ang, cang) {
    rangs=sin(ang);
    rangc=cos(ang);
    crangc=cos(cang);
    crangs=sin(cang);


    rorigD=new PVector();
    rorigD.set( orig);
    rorigD.sub( c);
    rdistOrig2 = rorigD.dot(rorigD);

    let temp = rorigD;
    rrorig=new PVector();
    rrorig.x=temp.x*rangs - temp.z*rangc;
    rrorig.y=temp.y;
    rrorig.z=temp.z*rangs + temp.x*rangc;
  }
  GetOuterRadius()
  {
    let ch=hgts.GetCloudLayer() ==null ? 0. : cloudHieght;
    return max(max( ch, hgts.AtmosphereSize()), hgts.GetMaxHieght());
  }

  ApplyAtmosphere( cc, scattering, col, c,
  r, at, ro, dir,sunDir, applyShadow, innert)
  {
    // get start and end points
    let arad=(r+at);
    let t = cc.b2c+ arad*arad;
    //assert( t >= 0.0);
    let st =sqrt(t);
    let tnear =  max( cc.negb-st, 0.);
    let tfar=innert > 0. ? innert : max( cc.negb+st, 0.);
    let cv =(sqrt(-cc.b2c)-r)/at;
    cv = constrain(1.-cv,0.,1.);
    cv*=cv;
    if ( tnear<=0.)
      cv=1.;
    let absorbtion =0.15;
    cv*=1.-exp(-absorbtion*(tfar-tnear));

    if ( applyShadow ) {

      let np0=PVector.add(rorigD,PVector.mult(dir,tnear));
      let np1=PVector.add(rorigD,PVector.mult(dir,tfar));
      let shad0=max( np0.dot(sunDir),0.);
      let shad1=max( np1.dot(sunDir),0.);
      cv *=min(shad0+shad1,1.);
    }
    return new PVector(col.x+cv*scattering.x*2.,col.y+cv*scattering.y*2,col.z+cv*scattering.z*2);
  }

  GetHieghtCubeMap( hpt) {
    let cc = new CubeCache();
    let h=hpt.get();
    h.sub(c);
    let ccmap= hgts.GetHeightCubeMap();
    let den=ccmap.sample(cc,hpt, rangs,rangc);
    return den+r2;
  }
  GetHieght( hpt,t) {
    // get pt
    let hi = new HitInfo( hpt, c);
    let puv= new PVector();
    puv.set( hi.m_hp);
    puv.x+= 35.;
    puv.y+=178.;
    puv.z+=256.;
    return  hgts.GetHieght(puv.x, puv.y,puv.z, t);
  }
  GetMaterial( hpt, t )
  {
    // get pt
    let hi = new HitInfo( hpt, c);
    let puv= new PVector();
    puv.set( hi.m_hp);
    puv.x+= 35.;
    puv.y+=178.;
    puv.z+=256.;
    let mt = hgts.GetMaterial( puv, hi.m_nrm, t);         
    // get bump ??
    let eps = 0.002;//0.001;
    let xstep = new PVector();
    xstep.set(hi.m_binormal);
    xstep.mult(eps);

    let h0 = hgts.GetHieght(puv.x-xstep.x, puv.y-xstep.y,puv.z-xstep.z, t);         
    let h1 = hgts.GetHieght(puv.x+xstep.x, puv.y+xstep.y,puv.z+xstep.z,t);         

    let zstep = new PVector();
    zstep.set(hi.m_tangent);
    zstep.mult(eps);
    let h2 = hgts.GetHieght(puv.x-zstep.x, puv.y-zstep.y,puv.z-zstep.z, t);         
    let h3 = hgts.GetHieght(puv.x+zstep.x, puv.y+zstep.y,puv.z+zstep.z,t);         

    let n = new PVector ( h0-h1,  2.0*eps, h2-h3 );
    n.normalize(); 

    // transform to texture space
    let rnrm = hi.Transform( n);
    mt.nrm=rnrm;

    mt.ao = hgts.GetAO( puv.x,puv.y, puv.z, t);
    return mt;
  }
  interp( t, dt, h, lh, py, ly)
  {
    // interpolate the intersection distance
    return  t - dt + dt*(lh-ly)/(py-ly-h+lh);
  }


  Sample( cc,lgt,ro, dir, mint, maxt, col, isphere, rv  )
  {
    rv.addSky=true;
    col.set(0.,0.,0.);
    rv.col=col;
    let skyw = 1.;
    //    let cloud = g_useClouds ? hgts.GetCloudLayer() : null;
    let cloudmap= g_useClouds ? hgts.GetCloudCubeMap() : null;
    let cloudDen=0.;
    cc.ccol.set(0.,0.,0.);

    let numHSamples=0;
    let t = -1.;

    let skipAll=false;
    let useFast=g_useDisplacement;
    let maxHieght=hgts.GetMaxHieght();
    if ( !useFast && maxHieght > 0. ) {
      let arad=(r2+maxHieght);
      let tb = cc.b2c+ arad*arad;
      if ( tb >= 0.0) {
        let stt =sqrt(tb);
        let t0 =  max( cc.negb-stt, 0.);
        let t1=t <= 0. ? max( cc.negb+stt, 0.) : t;

        let numSteps=g_useHiQuality ? 1./64. : 1./32.;//1./24;
        let dt=r2*numSteps;

        let tc=0.;
        if ( cloudmap != null)
        {
          let cct=t0>0. ? t0 : t1;
          tc= t> 0. ? t0 : cct;

          if ( tc>0.) {

            let dx=rorigD.x+dir.x*tc;
            let dy=rorigD.y+dir.y*tc;
            let dz=rorigD.z+dir.z*tc;           

            cloudDen=cloudmap.sample(cc,dx,dy,dz,-crangs,-crangc);
            let scalev = cloudmap.m_wSize*48;
            let detailStrength = 1.- min(tc*g_FovRatio*scalev*.9,1.);        
            if ( detailStrength >0 && g_useDetailMapping)
            {
              let fi =cloudmap.getDetailDir(  cc.dv, cc.detailDir);         
              let cdetail = g_NoiseGen.Get( cc.detailDir[0]*2.13, cc.detailDir[1]*2.13);
              cloudDen *=(1.+cdetail*.2);
            }
            cloudDen=smoothstep(0,.6,cloudDen);
            cloudDen*=cloudDen;
            let cl=max(dx*lgt._sd.x+dy*lgt._sd.y+dz*lgt._sd.z,0.)+.1;
            cc.ccol.set(cl,cl,cl);
            if ( t>0. && cloudDen>.99) {
              t0=t1+100.;
              skipAll=true;
              rv.addSky=false;
            }
          }
        }
        let rdir = cc.rdir;
        let rorig = rrorig;
        // transform into cubemap space

        rdir.x=dir.x*rangs - dir.z*rangc;
        rdir.y=dir.y;
        rdir.z=dir.z*rangs + dir.x*rangc;

        let ccmap= hgts.GetHeightCubeMap();      
        t1+=dt;
        // do first one outside
        let ldist2=arad;
        let lh=arad;

        for ( tv=t0+dt*.5;tv<t1;tv+=dt) {
          // precompute rotatin
          cc.dv[0]= rorig.x + tv *rdir.x;
          cc.dv[1]= rorig.y + tv *rdir.y;
          cc.dv[2]= rorig.z + tv *rdir.z;

          let dist2=cc.dv[0]*cc.dv[0]+cc.dv[1]*cc.dv[1]+cc.dv[2]*cc.dv[2];         
          let den=ccmap.sampleRSpace(cc);
          let h=den+r2;
          if (  dist2 <(h*h)) {
            t=interp(tv,dt,h,lh,sqrt(dist2),sqrt(ldist2));   
           // t=tv;
            break;
          }           
          lh=h;
          ldist2=dist2;    
          numHSamples++;
         // dt *=1.15;
          dt *=1.05;
        }
        // do interval mapping if hit extrusion

        if ( t < t1 && g_useHiQuality )
        {  
          dt*=.5;
          t-=dt;
          let lpamt=3 + (t<(arad) ? 4: 0);
          for(i=0;i<lpamt;i++) {
            cc.dv[0]= rorig.x + t *rdir.x;
            cc.dv[1]= rorig.y + t *rdir.y;
            cc.dv[2]= rorig.z + t *rdir.z;

            let dist2=cc.dv[0]*cc.dv[0]+cc.dv[1]*cc.dv[1]+cc.dv[2]*cc.dv[2];         
            let den=ccmap.sampleRSpace(cc); 
            let h=den+r2;     
            dt*=.5;           
            if ( dist2<(h*h))
              t-=dt;
            else            
              t+=dt;
          }
          numHSamples+=lpamt;
        }


        if ( t>0 && t<=tc) {
          cloudDen=0.;
        }
      }
    }
    else
    {
      t=isphere.Intersect(dir);
    }
    if ( t>0. && t < maxt && !skipAll)// && false) // hit
    {

      cc.hpt.x=rorigD.x + dir.x*t;
      cc.hpt.y=rorigD.y + dir.y*t;
      cc.hpt.z=rorigD.z + dir.z*t;

      cc.plNrm.set(cc.hpt);

      //  plNrm.mult(invRadius);
      //plNrm.normalize();

      let mt =null;
      let cmap=hgts.GetCubeMap();
      if (  g_useCubeMaps)
      {
        // apply rotation to light as well        
        cc.res=cmap.sample(cc,cc.plNrm, rangs,rangc,cc.res);
        mt = cc.mat;
        // only up close
        let scalev = cmap.m_wSize*48;
        let detailStrength = 1.- min(t*g_FovRatio*scalev*.9,1.);
        let detailval=0.;
        if ( detailStrength >0 && g_useDetailMapping)
        {
          let fi =cmap.getDetailDir(  cc.dv, cc.detailDir);

          g_NoiseGen.GetWithNormal( cc.detailDir[0]*2.13, cc.detailDir[1]*2.13, cc.detailNoise);
          detailval=cc.detailNoise[0];
          detailval *= detailStrength;

          for (i=0;i<3;i++)
          {
            cc.dnorm[i]= ((fi +1)%3)==i ? cc.detailNoise[1] : 0.;
            cc.dnorm[i] +=((fi +2)%3)==i ? cc.detailNoise[2] : 0.;
          }
        }
        let difDetail =( 1. + detailval*.2);
        mt.surfcol.x= cc.res[0]*difDetail;
        mt.surfcol.y= cc.res[1]*difDetail;
        mt.surfcol.z= cc.res[2]*difDetail;

        mt.nrm.x= cc.res[3] + cc.dnorm[0]*detailStrength*0.2;
        mt.nrm.y= cc.res[4] + cc.dnorm[1]*detailStrength*0.2;
        mt.nrm.z= cc.res[5] + cc.dnorm[2]*detailStrength*0.2;
        mt.nrm.normalize();
        mt.ao= cc.res[6]*difDetail;
        mt.specAmount= cc.res[7];

        mt.emiss.x= cc.res[8]*difDetail;
        mt.emiss.y= cc.res[9]*difDetail;
        mt.emiss.z= cc.res[10]*difDetail;
        if ( g_DebugAO) {
          let hv=mt.ao;//hgts.GetHeightCubeMap().sample(cc,cc.plNrm, rangs,rangc);
          mt.surfcol.x=hv;
          mt.surfcol.y=hv;
          mt.surfcol.z=hv;
        }
      }
      else
        mt=GetMaterial(  cc.hpt,t);

      let pNdolL=cc.plNrm.dot( lgt._sd);     
      let ao = max( (pNdolL+aoWrap)*invWrap,0.)+.1;
      ao*=mt.ao;

      let shad = max( (pNdolL+shadRap)*invShadWrap,0.);

      //      if ( !useFast &&
      if ( !useFast &&maxHieght > 0. && shad >0.) {
        let st=-1.;

        // do cloud shadows
        if ( cloudmap != null )  // do cloud shadows
        {
          // could do dir optimization
          st=intSphereOriginSimple( r2+maxHieght, cc.hpt, lgt._sd);

          let puv2 = PVector.add(cc.hpt,PVector.mult(lgt._sd,st));
          puv2.sub(c);
          let den=cloudmap.sample(cc,puv2, -crangs,-crangc);
          shad *= max(1. - den*3.,0.);
        }
        if (shad > .0 && shad <.6 ) {
          if (st<0.)
            st=intSphereOriginSimple( r2+maxHieght, cc.hpt, lgt._sd);

          let shadowStepSize=max(st/5.,maxHieght/3);
          let hcmap= hgts.GetHeightCubeMap();
          for (sht=0.5*shadowStepSize;sht<st;sht+=shadowStepSize) {
            let shpt=PVector.add(cc.hpt,PVector.mult( lgt._sd,sht));
            let dist2=shpt.dot(shpt);         
            let den=hcmap.sample(cc,shpt, rangs,rangc);
            let h=den+r2;
            h*=h;
            if (  dist2 <h) {

              shad*=0.;
              break;
            }
          }
        }
      }
      col = lgt.getShading( ao, shad, mt.nrm,  mt, col);
      // add in atmopsphere
      rv.addSky=false;
    }
    col = lerp( col, cc.ccol, cloudDen );
    let atmosphereHieght= hgts.AtmosphereSize();
    if ( atmosphereHieght > 0.0  && g_useAtmosphere)
    {
      col = ApplyAtmosphere(cc,  hgts.AtmosphereColor(), col, c, r2,atmosphereHieght,
      ro, dir, lgt._sd,  hgts.ShadowAtmosphere(), t);
    }
    rv.col=col;
    //  if ( g_DebugAO)
    //  rv.col=ne PVector(float(numHSamples)/32.,float(numHSamples)/10.,float(numHSamples)/10.);

    return rv;
  }
}

