class GammaTable
{
  tSize = 2048;
  let tSizef = float(tSize);
  let g_tab = new Array(tSize);
  constructor()
  {
    for (i = 0; i < tSize; i++)
    {
      g_tab[i] = int(pow( float(i)/tSize, 1/2.2 )*255.);
    }
  }
  Get( v )
  {
    let iv = max(min(int(v*tSizef),tSize-1),0);
    return g_tab[ iv];
  }
}
let g_GTable = new GammaTable();

