function lerp( a, b, t)
{
  return new PVector( lerp(a.x,b.x,t),lerp(a.y,b.y,t),lerp(a.z,b.z,t));
}
function smoothstep(edge0, edge1, x)
{
  x =  min(max((x - edge0) / (edge1 - edge0),0.0),1.0);
  return x*x*(3-2*x);
}
function smoothblend( a, b, x)
{
  x = x*x*(3-2*x);
  return lerp(a,b,x);
}
class Frustum
{
  let n = new Array(4);
  let d = new Array(4);

  constructor(o, di) {
    for (i=0;i<4;i++) {
      n[i]=di[i].cross(di[(i+1)%4]);
      n[i].normalize();
      d[i]=o.dot(n[i]);
    }
  }
  Intersect( c, r)
  {
    let rv= true;
    for (i=0;i<4;i++) {
      let dv=c.dot(n[i])-d[i];
      if ( dv<-r) {
        rv=false;
      }
    }
    return rv;
  }
};



