let g_FovRatio = 0;

function SetFovRatio( fov, w )
{
  g_FovRatio = tan(radians(fov)/2.)  /(float(w)/2.);
}

function CalcNoiseOctaves( t, s, octSize, lac )
{
  if (t<0.)
    return (int)-t;
  let pixSize = t*g_FovRatio*octSize ; // 8 pixels is done by bump mapping
  let si = 1/s;
  let numOctaves = 0;
  while( si > pixSize)
  {
    si*=lac;
    numOctaves++;
    if (numOctaves >12)
      return numOctaves;
  }
  return numOctaves;
}

