class Moon extends BaseHF
{
  let omega;
  lacunarity = 2;
  step=0.;
  let stepsize;
  let scale;
  let hgt;
  let canyon;
  constructor()
  {  
    Setup();
  }
  function Setup() {
    let c= random(0.2,0.6);
    matGrey.surfcol=new PVector(c,c,c);
    matWhite.surfcol=randomCol(max( random(-0.05,0.05),0.));

    let H = random(.2,.5);
    omega = pow (lacunarity, (-.5)-H);
    step=random(0.05,0.2);
    stepsize=random(0.1,0.5);
    scale = random(1.,3.);
    hgt=random(0.4,2.);
    canyon=random(0.0,0.7);
  }
  // http://www.renderman.org/RMR/Shaders/KMShaders/KMLuna.sl
  crater( x, y, z, rad){
     x-= 35.;
    y-=178.;
    z-=256.+2.;
    let cradist=(z*z+y*y);
    let d= 1. - min(sqrt(cradist)/rad,1.);
    let h =smoothstep(0,1.,d)-smoothstep(0.3,.4,d);
    return h;
  }
  chaos( isAo, x,  y, z, t)
  {
    let crat=crater(x,y,z,.1);
    x*=scale;
    y*=scale;
    z*=scale;
    let lacunarity = 2;
    let goct = CalcNoiseOctaves(t,4.,0.5,1./lacunarity);
    let cndnoise=g_NoiseGen.Fbm3( x*1.124+154.35,y*1.126+154.35,z*1.467+154.35, goct, 0.6,lacunarity);
    let cand= smoothstep(0.1,0.4,cndnoise);


    if (isAo==false)
      return (g_NoiseGen.Fbm3( x,y,z, goct, omega,lacunarity))-cand*canyon+crat;
    else
      return g_NoiseGen.FbmAO3( x,y,z, goct, omega,lacunarity)*(1-cand*.5);
  }
  GetHieght(x,  y, z, t)
  {
    let r= max(( chaos( false, x,y,z,t) *.35+.5)*GetMaxHieght(),0.);   
    return r;
  }
  GetMaxHieght() {
    return  0.07*hgt;
  }
  GetAO(x, y, z, t)
  {
    return sqrt(min(chaos( true, x,y,z,t)*4.,1.))*chaos( false, x,y,z,t);
  }
  GetMaterial(p, n, t)
  {
    let fp=chaos( false, p.x,p.y,p.z,t);
    fp = smoothstep(step,step+stepsize,fp);
    return lerp(matGrey, matWhite, fp);
  }
}

