  new ColorPts(-0.2500, new PVector(  0,   0, 255)), // shallow
  new ColorPts(0.0000, new PVector(0, 128, 255)), // shore
  new ColorPts(0.0625, new PVector(240, 240,  64)), // sand
  new ColorPts(0.1250, new PVector( 32, 160,   0)), // grass
  new ColorPts(0.3750, new PVector(224, 224,   0)), // dirt
  new ColorPts(0.7500, new PVector(128, 128, 128)), // rock
