function GetGradientColor( pts, v )
{
  let idx = 0;
  v = min(max(v,-1),1);
  while( idx < pts.length && pts[idx].v < v)
    idx++;

  assert( idx !=0);
  let bl = smoothstep( pts[idx-1].v,pts[idx].v, v);
  let r = lerp( pts[idx-1].c,pts[idx].c, bl);
  r.mult(1./255.);
  return r;
}

class EarthClouds implements CloudLayer
{
  offset = 0.1;
  scalev = 2.;
  GetDensity( x, y, z, t)
  {
    let goct = CalcNoiseOctaves(t,2.,1.,1./2.);
    let invOffset = 1./(1. + offset);
    let result = VLFbm3( x*scalev, y*scalev, z*scalev, goct, 0.7, 2.,0.5);
    result += offset;
    result = max(result*invOffset, 0.);
    return result;
  }
};

class Earth extends BaseHF
{
