  {
    let lacunarity = 2.189;
    let omega = 0.5;

    let goct = CalcNoiseOctaves(t,2.,0.5,1./lacunarity);

    if (isAo==false)
      return g_NoiseGen.Fbm3( x*2., y*2., z*2., goct, omega,lacunarity);
    else
      return g_NoiseGen.FbmAO3( x*2.,y*2.,z*2., goct, omega,lacunarity);
  }
  GetHieght(x,  y,z, t)
  {
    return max(chaos( false, x,y,z,t),groundH)*GetMaxHieght();
  }
  GetMaxHieght() {
    return  0.05;
  }
  GetAO(x, y, z, t)
  {  
    let h =chaos( false, x,y,z,t);
    let aov=chaos( true, x,y,z,t);
    let v = h<groundH ? 1. : sqrt(min(aov*6.,1.));
    return v;
