class Earth2 extends BaseHF
{
  m_earthClouds = null;

  seaLevel = 0.0;
  constructor()
  {
   m_earthClouds = new EarthClouds();
  }

  chaos( isAo, x, y, z, t)
  {
    let lacunarity = 2.189;
    let omega = 0.5;

    let goct = CalcNoiseOctaves(t,4.,0.5,1./lacunarity);
    if (isAo==false)
      return g_NoiseGen.Fbm3( x*4., y*4, z*4., goct, omega,lacunarity);
    else
      return g_NoiseGen.FbmAO3( x*4.,y*4, z*4., goct, omega,lacunarity);
  }
  GetHieght(x, y, z, t)
  {
    return max(chaos( false, x,y,z,t),seaLevel)*GetMaxHieght();
  }
  GetMaxHieght() {
    return  0.05;
  }
  GetAO(x, y, z, t)
  {
    let h =chaos( false, x,y,z,t);
    let aov=chaos( true, x,y,z,t);
    let v = h<seaLevel ? 1. : sqrt(min(aov*6.,1.));
    return v;
  }

  GetMaterial(p, n, t)
  {
    let h= chaos( false, p.x,p.y,p.z,t);

    let lat_scale = 0.95;
    let nonlinear = 0.0;
    let purt_scale = .9;
    let map_exp = 0;

    let latitude = abs(n.y);
    latitude += h*(nonlinear*(1-latitude) + purt_scale);
    if (map_exp > 0)
      latitude = lat_scale * pow(latitude,map_exp);
    else latitude *= lat_scale;

    let c;
    if ( h > seaLevel)
    {
      c = GetGradientColor( g_KMTerrainColor, latitude);
      c.mult(255.);
      // mottle the let some 
      let mottle_limit = 0.75;
      let mottle_scale = 20;
      let mottle_dim = .25;
      let mottle_mag = .02;

      if (latitude < mottle_limit)
      {
        let purt= g_NoiseGen.Fbm3( p.x*mottle_scale,p.y*mottle_scale, p.z*mottle_scale, 6, 0.25,2.);
        let mottle = new PVector(0.5,0.175,0.5);
        mottle.mult( purt * mottle_mag);
        c.add( mottle);
      }
    }
    else
    {
      c = new PVector(.1,.2,.5);
      let ice_caps = 0.9;
      if (ice_caps > 0  &&  latitude > ice_caps)
        c = new PVector(.1,.2,.5); 
      else
      {
        // let color of water to darken deeper seas 
        let depth_scale = 1;
        let depth_max = .5;
        h -= seaLevel;
        h *= depth_scale;
        h = max (h, -depth_max);
        c.mult(1+h);
      }
    }
    //c.mult(shade);
    // c.set(latitude,latitude,latitude);
    let em = new Material( c); 
    em.specAmount =smoothstep(seaLevel+0.1,seaLevel-0.1,h)
      + 0.075;
    return em;
  }
  GetCloudLayer() {   
    return m_earthClouds;
  }

  AtmosphereSize() {
    return 0.1;
  }
  AtmosphereColor() {
    return new PVector(1.,1.,8.);
  }
  hasRings() {
    return false;
  }
}

