function randomCol(delta ) {
  let r = new Array(3);
  let ri = int(random)(0.,2.99);
  r[ri]=random(0.6,1.0);

  r[(ri+1)%3]=r[ri]*(1.-delta);
  r[(ri+2)%3]=r[ri]*(1.-3.*delta);
  return new PVector(r[0],r[1],r[2]);
}
//http://www.renderman.org/RMR/Shaders/KMShaders/KMVenus.sl
class Venus extends BaseHF
{
  let scale;
  let twist;

  constructor()
  {
    Setup();
  }
  function Setup() {
    matDarkVenus.surfcol = randomCol(random(0.1,0.3));
    matBrightVenus.surfcol=randomCol( max( random(-0.05,0.005),0.));
    if ( random(1.)<.5)
      scale = random(2.,4.);
    else
      scale = random(0.25,0.9);

    twist=random(0.32,0.6);//0.42
  }
  chaos( isAo, x,  y,z, ny, t)
  {
    x-= 35.;
    y-=178.;
    z-=256.+2.;

    x *=scale;
    y*=scale;
    z *=scale; 

    let rsq = x*x + z*z;
    let angle =  twist * 2. * PI * rsq;

    let sine = sin(angle);
    let cosine = cos(angle);

    let px = x * cosine - z * sine;
    let py = x* sine + z * cosine;
    let pz = y;
    let goct = CalcNoiseOctaves(t,1.,1.,1./2.);

    // add in pertub depending on equator

    pz += g_NoiseGen.Fbm3( x, y,z, goct, 0.65, 2.) * (1.-abs(ny));
    let result = g_NoiseGen.Fbm3( px, py, pz, goct, 0.65, 2.);

    result = abs( 1. + 0.6*result);

    return result;
  }

  GetMaterial(p, n, t)
  {
    let shade=chaos( true, p.x,p.y,p.z, n.y, t);   
    let matLavav =  lerp( matDarkVenus,matBrightVenus,shade);
    return matLavav;
  }
}
ColorPts[] randomColorPts(amt, colTable) {
  let v = new Array(amt);
  let ctable = new Array(colTable);

  let c0=new PVector(0.7+random(0.4),0.3+random(0.5),random(.3));
  let c1=new PVector(0.7+random(0.4),0.3+random(0.5),random(.3));
  for (let i=0;i<colTable;i++) {
    if (random(1.)<.8)
      ctable[i]=lerp(c0,c1,random(0.,1.));
    else
      ctable[i]=new PVector(1.,1.,1.);
  }
  let s=-1.001;
  let ci=-1;
  let pi=0;
  for(let i=0; i<amt;i++) {
    if ( i==amt-1)
      s = max(s,1.);
    let cci= int(random)(0.,float(colTable)-.001);
    if ( ci!=cci) {
      v[pi++]=new ColorPts(s, PVector.mult(ctable[int(random)(0.,float(colTable)-.001)],255.));
    }
    ci=cci;
    s += random(0.025, 6./float(amt));
  }
  return v;
}
