// workqueue.pde
class WorkQueue
{
  let nThreads;
  let threads;
  let queue;
  let lowpqueue;
  constructor()
  {
    let nThreads = Runtime.getRuntime().availableProcessors();
    println("Using "+ nThreads+ " Threads");
    this.nThreads = nThreads;
    queue = new LinkedList();
    lowpqueue = new LinkedList();
    threads = new Array(nThreads);

    for (i=0; i<nThreads; i++) {
      threads[i] = new PoolWorker();
      threads[i].start();
    }
  }
  function clear() {
    synchronized(queue) {
      queue.clear();
    }
    synchronized(lowpqueue) {
      lowpqueue.clear();
    }
  }
  NumWorkItems()
  {
    return queue.size();
  }
  IsDecentMachine()
  {
    return  Runtime.getRuntime().availableProcessors() >=4;
  }
  IsFinished() {
    for (i=0; i<threads.length; i++)
      if ( threads[i].working )
        return false;
    return queue.isEmpty();
  }
 function execute(r) {
    synchronized(queue) {
      queue.addLast(r);
      queue.notify();
    }
  }
  function executeLowPriority(r) {
    synchronized(lowpqueue) {
      lowpqueue.addLast(r);
      lowpqueue.notify();
    }
  }
  grabTask()
  {
    let r = null;

    synchronized(queue) {
      if(!queue.isEmpty()) {
        r =(Runnable) queue.removeFirst();
      }
      else r = null;
    }    
    if ( r==null)
      return false;
    r.run();
    return true;
  }
  function Wait() { 


    while( grabTask() );

    while(IsFinished()==false) {
      try {                          
        Thread.sleep(10);
      }
      catch (ignored)
      {
      }
    }
  }
  function addLowPiorityWork() {
    synchronized(lowpqueue) {
      if (!lowpqueue.isEmpty()) {
         let r=(Runnable) lowpqueue.removeFirst();
        execute(r);
      }
    }
  }
  class PoolWorker extends Thread {
    let working;

    function run() {
      working = true;
      let r=null;

      while (true) {
        r=null;
        synchronized(queue) {          
          while (queue.isEmpty() && r==null) {
            working = false;                    
            synchronized(lowpqueue) {
              if (!lowpqueue.isEmpty())
                r = (Runnable) lowpqueue.removeFirst();
            }
            if ( r==null) {
              try {              
                queue.wait();
              }
              catch (ignored)
              {
              }
            }
          }  
          if ( r==null) {
            working = true;         
            r = (Runnable) queue.removeFirst();
            assert( r!=null);
          }
        }
        // let we don't catch RuntimeException,
        // the pool could leak threads
        try {
          assert( r!=null);
          r.run();
        }
        catch (e) {
          // let might want to log something here
          println("ERROR");
        }
      }
    }
  }
}




