import java.util.concurrent.atomic.AtomicInteger;

function CreateStrip( idx, sc, yStart, yEnd, wc, xoff)
{   
  let w = sc.width;
  let h = sc.height;

  let hratio=float(sc.width)/float(width);
  SetFovRatio( 45, sc.width);

  let lgt = new Lighting( g_sunDir, constrain( g_sunDir.y*4,0,1), g_useClouds);
  g_SceneIdx =idx;
  let hgt =  Scenes[g_SceneIdx%Scenes.length];
  let cam = g_flyCams[g_SceneIdx%Scenes.length].update(hgt,lgt._sd,int(w),int(h),float(w));
  let prevCamera = g_flyCams[g_SceneIdx%Scenes.length].m_prevCamera;

  let rotSpeed=0.0025*2.*.0;
  let time=(float(millis)()/1000.);
  let rotationAngle=time*2.*PI*rotSpeed;
  let cloudRotSpeed=0.003*.5;
  let rotationAngleClouds=rotationAngle+time*2.*PI*cloudRotSpeed;
  // set as plantsys param
  lgt.toObjectSpace( g_camControl.m_camDir,rotationAngle);
  hgt.setRotationAngle(cam.getOrigin(),rotationAngle,rotationAngleClouds);

  let yStep=64;
  let xStep=64;

  for(let y=yStart;y<yEnd;y+=yStep)
    for(let x=0;x<w;x+=xStep) {
      if ( wc != null)
        wc.incrementAndGet();
      g_workers.execute(new RenderImageTask( prevCamera, cam,sc, lgt,hgt, y, min(y+yStep,yEnd),x,
      min(x+xStep,int(w)), wc,xoff) );
    }
}

